  private rewardsApplied = false;
  private lastReward: { currency: number; coinType: CoinType; coinValue: number } | undefined;
  private metaOpen = false;
  private metaMessage = '';
  private viewZoom = 1;
  private debugTouchCount = 0;

  constructor(mgr: GameDataManager) {
    this.mgr = mgr;

    // 全屏背景（不缩放，铺满包括信箱边在内的整个窗口）
    this.screenBgNode = Node();
    this.screenDraw = DrawNode();
    this.screenDraw.addTo(this.screenBgNode);
    this.screenBgNode.addTo(Director.entry);

    // 游戏内容根（按设计尺寸缩放）
    this.gameRoot = Node();
    this.gameRoot.addTo(Director.entry);

    this.bgLayer = Node();
    this.hudLayer = Node();
    this.cardLayer = Node();
    this.coinLayer = Node();
    this.actionLayer = Node();
    this.overlayLayer = Node();
    this.fxLayer = Node();
    this.bgLayer.addTo(this.gameRoot);
    this.hudLayer.addTo(this.gameRoot);
    this.cardLayer.addTo(this.gameRoot);
    this.coinLayer.addTo(this.gameRoot);
    this.actionLayer.addTo(this.gameRoot);
    this.overlayLayer.addTo(this.gameRoot);
    this.fxLayer.addTo(this.gameRoot);

    // 触摸层：覆盖整个设计区域，统一做命中检测与拖拽跟踪。
    // swallowTouches 独占事件，下面的按钮/卡牌/硬币只作为尺寸数据供 convertToNodeSpace 命中。
    this.touchLayer = Node();
    this.touchLayer.size = Size(DESIGN_W, DESIGN_H);
    this.touchLayer.position = Vec2(0, 0);
    this.touchLayer.anchor = Vec2(0.5, 0.5);
    this.touchLayer.touchEnabled = true;
    this.touchLayer.swallowTouches = true;
    this.touchLayer.z = 1000;
    this.touchLayer.onTapBegan((t) => this.onTouchBegan(this.designPoint(t)));
    this.touchLayer.onTapMoved((t) => this.onDragMove(this.designPoint(t)));
    this.touchLayer.onTapEnded((t) => this.onDragEnd(this.designPoint(t)));
    this.touchLayer.addTo(this.gameRoot);

    this.buildStatic();
    this.updateScale();

    // 窗口尺寸变化时重新适配
    Director.entry.onAppChange((name) => {
      if (name === 'Size') this.updateScale();
    });
  }

  // 根据当前窗口比例缩放摄像机，保证 720x1280 设计区域完整可见。
  // 使用 Camera2D.zoom 而非节点 scale：引擎会把相机缩放自动应用到触摸坐标换算。
  private updateScale(): void {
    const w = View.size.width;
    const h = View.size.height;
    const zoom = Math.min(w / DESIGN_W, h / DESIGN_H);
    this.viewZoom = zoom;
    const camera = tolua.cast(Director.currentCamera, TypeName.Camera2D);
    if (camera) {
      camera.zoom = zoom;
    }

    // 重绘全屏背景，铺满相机可见范围（含信箱边）
    const vw = w / zoom;
    const vh = h / zoom;
    this.screenDraw.clear();
    this.screenDraw.drawPolygon(
      [Vec2(-vw / 2, -vh / 2), Vec2(vw / 2, -vh / 2), Vec2(vw / 2, vh / 2), Vec2(-vw / 2, vh / 2)],
      C_BG,
      0,
    );
  }

  // 构建静态元素（背景面板、按钮）
  private buildStatic(): void {
    // 设计区域背景与面板
    const d = DrawNode();
    d.drawPolygon(rectVerts(0, 0, DESIGN_W, DESIGN_H), C_BG, 0);
    d.drawPolygon(rectVerts(0, 95, 664, 720), C_PANEL, 3, C_PANEL_BORDER);
    d.drawPolygon(rectVerts(0, -498, 664, 280), C_PANEL, 3, C_PANEL_BORDER);
    d.drawSegment(Vec2(-332, 470), Vec2(332, 470), 2, C_PANEL_BORDER);
    d.addTo(this.bgLayer);

    // 顶部 HUD：确定按钮（高亮）
    const confirmDraw = DrawNode();
    confirmDraw.drawPolygon(
      rectVerts(this.confirmBtn.x, this.confirmBtn.y, this.confirmBtn.w, this.confirmBtn.h),
      C_CONFIRM, 2, C_CONFIRM_BORDER,
    );
    confirmDraw.addTo(this.actionLayer);
    makeLabel(this.actionLayer, '确定', this.confirmBtn.x, this.confirmBtn.y, 20, C_TEXT);

    // 底部动作栏：结束回合按钮
    const endDraw = DrawNode();
    endDraw.drawPolygon(
      rectVerts(this.endTurnBtn.x, this.endTurnBtn.y, this.endTurnBtn.w, this.endTurnBtn.h),
      C_ENDTURN, 2, C_CONFIRM_BORDER,
    );
    endDraw.addTo(this.actionLayer);
    makeLabel(this.actionLayer, '结束回合', this.endTurnBtn.x, this.endTurnBtn.y, 20, C_TEXT);
  }

  // 根据当前游戏状态刷新动态内容
  refresh(): void {
    if (this.selectedCardId !== undefined) {
      const c = this.mgr.findCard(this.selectedCardId);
      if (!c || c.eliminated) this.selectedCardId = undefined;
    }
