    makeLabel(this.hudLayer, '需消除 ' + s.eliminatedCount + '/' + s.targetCount + ' 张', 0, 545, 18, C_TEXT_DIM);
    makeLabel(this.hudLayer, '回合 ' + s.turn, 120, 585, 22, C_TEXT);
