  // 格式化卡牌当前算式
  private equationText(card: Card): string {
    if (card.coins.length === 0) return '算式：0';
    let s = '算式：0';
    for (let i = 0; i < card.coins.length; i++) {
      const c = card.coins[i];
      if (c.type === CoinType.Multiply) {
        s += c.op === 'div' ? ' ÷ ' + c.value : ' × ' + c.value;
      } else {
