  // ===== 胜负、关卡流转与局外养成（第五/六步） =====

  private updateOverlay(): void {
    const s = this.mgr.state;
    this.overlayLayer.removeAllChildren();
    this.overlayButtons = [];

    if (s.status === 'playing') {
      this.metaOpen = false;
      this.metaMessage = '';
      return;
    }

    // 半透明遮罩
    const dim = DrawNode();
    dim.drawPolygon(rectVerts(0, 0, DESIGN_W, DESIGN_H), Color(6, 8, 20, 205), 0);
    dim.addTo(this.overlayLayer);

    if (this.metaOpen) {
      this.renderMetaPanel();
      return;
    }

    // 中央面板
    const panel = DrawNode();
    panel.drawPolygon(rectVerts(0, 0, 520, 380), C_PANEL, 4, C_PANEL_BORDER);
    panel.addTo(this.overlayLayer);

    if (s.status === 'lost') {
      makeLabel(this.overlayLayer, '游戏失败', 0, 120, 34, C_DANGER);
      makeLabel(this.overlayLayer, '生命归零，未能完成本关', 0, 60, 18, C_TEXT_DIM);
      makeLabel(this.overlayLayer, '第 ' + s.level + ' 关 · 已消除 ' + s.eliminatedCount + '/' + s.targetCount + ' 张', 0, 22, 16, C_TEXT_DIM);
      this.addOverlayButton('重试', 0, -120, 220, 50, C_ENDTURN, 'retry');
    } else if (s.status === 'complete') {
      if (!this.rewardsApplied) { this.lastReward = this.mgr.applyWinRewards(); this.rewardsApplied = true; }
      makeLabel(this.overlayLayer, '全部通关！', 0, 120, 34, Color(120, 220, 150, 255));
      makeLabel(this.overlayLayer, '你完成了全部 ' + GameDataManager.MAX_LEVEL + ' 关', 0, 60, 18, C_TEXT);
      makeLabel(this.overlayLayer, '总货币 ' + s.currency, 0, 22, 16, C_TEXT_DIM);
      this.addOverlayButton('重新开始', 0, -120, 220, 50, C_CONFIRM, 'restart');
    } else {
      if (!this.rewardsApplied) { this.lastReward = this.mgr.applyWinRewards(); this.rewardsApplied = true; }
      makeLabel(this.overlayLayer, '关卡完成！', 0, 120, 34, Color(120, 220, 150, 255));
      makeLabel(this.overlayLayer, '已消除 ' + s.eliminatedCount + '/' + s.targetCount + ' 张 · 生命 ' + s.hp + '/' + s.maxHp, 0, 60, 18, C_TEXT);
      let rewardText = '货币 +0 · 新硬币 +1';
      if (this.lastReward) {
        rewardText = '货币 +' + this.lastReward.currency + ' · 新硬币：' + coinTypeName(this.lastReward.coinType) + ' ' + this.lastReward.coinValue;
      }
      makeLabel(this.overlayLayer, rewardText, 0, 22, 16, C_TEXT_DIM);
      this.addOverlayButton('下一关', 0, -90, 220, 46, C_CONFIRM, 'next');
      this.addOverlayButton('养成', 0, -155, 220, 46, Color(90, 120, 200, 255), 'meta');
    }
  }

  private renderMetaPanel(): void {
    const panel = DrawNode();
    panel.drawPolygon(rectVerts(0, 0, 640, 560), C_PANEL, 4, C_PANEL_BORDER);
    panel.addTo(this.overlayLayer);

    const s = this.mgr.state;
    makeLabel(this.overlayLayer, '局外养成', 0, 230, 30, Color(120, 220, 150, 255));
    makeLabel(this.overlayLayer, '货币 ' + s.currency + ' · 血量上限 ' + s.maxHp + ' · 删除次数 ' + this.mgr.deleteCredits, 0, 180, 16, C_TEXT);
    makeLabel(this.overlayLayer, '扫荡奖励按最高关卡计，货币上限 1000', 0, 148, 13, C_TEXT_DIM);
    if (this.metaMessage !== '') {
      makeLabel(this.overlayLayer, this.metaMessage, 0, 112, 14, Color(120, 220, 150, 255));
    }

    this.addOverlayButton('合成硬币', 0, 60, 300, 44, Color(90, 120, 200, 255), 'synthesize');
    this.addOverlayButton('强化血量（100）', 0, 4, 300, 44, C_ENDTURN, 'upgradeHp');
    this.addOverlayButton('强化删除次数（80）', 0, -52, 300, 44, C_ENDTURN, 'upgradeDelete');
    this.addOverlayButton('删除一枚硬币', 0, -108, 300, 44, Color(150, 70, 70, 255), 'delete');
    this.addOverlayButton('扫荡', 0, -164, 300, 44, C_CONFIRM, 'sweep');
    this.addOverlayButton('返回', 0, -230, 300, 44, Color(90, 110, 160, 255), 'back');
  }


