// 硬币类型对应的颜色
function coinColor(type: CoinType): Color.Type {
  switch (type) {
    case CoinType.Normal: return Color(84, 160, 255, 255);
    case CoinType.Multiply: return Color(255, 140, 82, 255);
    case CoinType.Freeze: return Color(120, 210, 255, 255);
    case CoinType.Discount: return Color(186, 140, 255, 255);
    case CoinType.Copy: return Color(255, 120, 200, 255);
    case CoinType.Wild: return Color(255, 208, 90, 255);
    case CoinType.Growth: return Color(140, 255, 170, 255);
    case CoinType.Heal: return Color(120, 224, 140, 255);
    case CoinType.Disturb: return Color(255, 92, 92, 255);
    default: return Color(200, 200, 200, 255);
  }
}

// 硬币芯片显示文本（按类型显示有意义的符号/数值）
function coinChipText(type: CoinType, value: number): string {
  switch (type) {
    case CoinType.Freeze: return '冻';
    case CoinType.Discount: return value + '%';
    case CoinType.Copy: return '复';
    case CoinType.Wild: return '万';
    case CoinType.Heal: return '+' + value;
    case CoinType.Growth: return '' + value;
    case CoinType.Normal:
    case CoinType.Multiply:
    case CoinType.Disturb:
    default: return '' + value;
  }
}

// 以中心点为基准的矩形顶点
function rectVerts(cx: number, cy: number, w: number, h: number): Vec2.Type[] {
  return [
    Vec2(cx - w / 2, cy - h / 2),
    Vec2(cx + w / 2, cy - h / 2),
    Vec2(cx + w / 2, cy + h / 2),
    Vec2(cx - w / 2, cy + h / 2),
  ];
}

// 便捷创建居中文本
function makeLabel(
  parent: Node.Type,
  text: string,
  x: number,
  y: number,
  size: number,
  color: Color.Type,
  anchor?: Vec2.Type,
): Label.Type | undefined {
  const l = Label('sarasa-mono-sc-regular', size);
  if (!l) return undefined;
  l.text = text;
  l.position = Vec2(x, y);
  l.anchor = anchor ? anchor : Vec2(0.5, 0.5);
  l.color = color;
  l.addTo(parent);
  return l;
}

