  // ===== 触摸交互（第三步） =====

  // 把触摸事件坐标换算为设计中心坐标（原点在屏幕中心，X 向右，Y 向上）。
  // touch.location 是 touchLayer 的本地坐标（左下角为原点，范围 0..DESIGN_W / 0..DESIGN_H），
  // 引擎在派发事件时已自动应用 Camera2D 的逆变换（含缩放、旋转、平移），
  // 因此这里只需把左下角原点平移为屏幕中心原点，避免依赖 worldLocation 的缩放语义。
  private designPoint(t: Touch.Type): Vec2.Type {
    return Vec2(
      t.location.x - DESIGN_W / 2,
      t.location.y - DESIGN_H / 2,
    );
  }

  // 用节点自身 size 做命中检测：世界坐标转节点本地，判断是否落在 [0,size] 内。
  private inNode(p: Vec2.Type, node: Node.Type): boolean {
    const local = node.convertToNodeSpace(p);
    return local.x >= 0 && local.x <= node.size.width &&
      local.y >= 0 && local.y <= node.size.height;
  }

  private inRect(p: Vec2.Type, r: { x: number; y: number; w: number; h: number }): boolean {
    return p.x >= r.x - r.w / 2 && p.x <= r.x + r.w / 2 &&
      p.y >= r.y - r.h / 2 && p.y <= r.y + r.h / 2;
  }

  private cardAt(p: Vec2.Type): number | undefined {
    for (let i = 0; i < this.cardNodes.length; i++) {
      if (this.inNode(p, this.cardNodes[i].node)) return this.cardNodes[i].id;
    }
    return undefined;
