  // 用节点自身 size 做命中检测：世界坐标转节点本地，判断是否落在 [0,size] 内。
  private inNode(p: Vec2.Type, node: Node.Type): boolean {
    const local = node.convertToNodeSpace(p);
    return local.x >= 0 && local.x <= node.size.width &&
      local.y >= 0 && local.y <= node.size.height;
  }

  private inRect(p: Vec2.Type, r: { x: number; y: number; w: number; h: number }): boolean {
    return p.x >= r.x - r.w / 2 && p.x <= r.x + r.w / 2 &&
      p.y >= r.y - r.h / 2 && p.y <= r.y + r.h / 2;
  }

  private cardAt(p: Vec2.Type): number | undefined {
    for (let i = 0; i < this.cardNodes.length; i++) {
      if (this.inNode(p, this.cardNodes[i].node)) return this.cardNodes[i].id;
    }
    return undefined;
  }

  private chipAt(p: Vec2.Type): ChipRef | undefined {
    // 已放置芯片优先（在卡牌上，视觉层级更高）
    for (let i = 0; i < this.chipNodes.length; i++) {
      const c = this.chipNodes[i];
      if (c.kind === 'placed' && this.inNode(p, c.node)) return c;
    }
    for (let i = 0; i < this.chipNodes.length; i++) {
      const c = this.chipNodes[i];
      if (c.kind === 'inventory' && c.count > 0 && this.inNode(p, c.node)) return c;
    }
    return undefined;
  }

  private onTouchBegan(p: Vec2.Type): void {
    this.lastPos = p;
    this.dragMoved = 0;
    this.dragging = undefined;

    // 弹窗期间仅响应弹窗按钮
    if (this.overlayButtons.length > 0) {
      for (let i = 0; i < this.overlayButtons.length; i++) {
        if (this.inRect(p, this.overlayButtons[i])) this.handleOverlayAction(this.overlayButtons[i].action);
      }
      return;
    }

    // 按钮优先
    if (this.inRect(p, this.confirmBtn)) { this.doConfirm(); return; }
    if (this.inRect(p, this.endTurnBtn)) { this.doEndTurn(); return; }

    // 硬币芯片（背包 + 已放置）
    const chip = this.chipAt(p);
    if (chip) {
      if (chip.kind === 'placed' && chip.cardId !== undefined && chip.index !== undefined) {
        this.dragging = { kind: 'placed', cardId: chip.cardId, index: chip.index };
      } else {
        this.dragging = { kind: 'inventory', type: chip.type, value: chip.value };
      }
      this.makeGhost(chip.type, chip.value, p);
      return;
    }

    // 卡牌选中
    const cardId = this.cardAt(p);
    if (cardId !== undefined) {
      this.selectedCardId = cardId;
      this.refresh();
    }
  }

  private onDragMove(p: Vec2.Type): void {
    if (this.lastPos) {
      this.dragMoved += Math.abs(p.x - this.lastPos.x) + Math.abs(p.y - this.lastPos.y);
    }
    this.lastPos = p;
    if (this.dragging && this.dragGhost) this.dragGhost.position = p;
  }

  private onDragEnd(p: Vec2.Type): void {
    const drag = this.dragging;
    this.dragging = undefined;
    this.hideGhost();
    if (!drag) return;

    const isTap = this.dragMoved < 14;

    if (drag.kind === 'inventory') {
      if (isTap) return;
      const cardId = this.cardAt(p);
      if (cardId !== undefined) {
        this.mgr.placeCoinOnCard(cardId, drag.type, drag.value);
        this.refresh();
      }
    } else {
      if (isTap) {
        this.mgr.togglePlacedCoin(drag.cardId, drag.index);
        this.refresh();
        return;
      }
      const cardId = this.cardAt(p);
      if (cardId === undefined) {
        this.mgr.removePlacedCoin(drag.cardId, drag.index);
      } else if (cardId !== drag.cardId) {
        this.mgr.movePlacedCoin(drag.cardId, drag.index, cardId);
      }
      this.refresh();
    }
  }

