    fill: Color.Type,
    border: Color.Type,
    onTap: () => void,
  ): void {
    const node = Node();
    node.position = Vec2(rect.x, rect.y);
    node.size = Size(rect.w, rect.h);
    node.anchor = Vec2(0.5, 0.5);
    const d = DrawNode();
    d.drawPolygon(rectVerts(rect.w / 2, rect.h / 2, rect.w, rect.h), fill, 2, border);
    d.addTo(node);
    makeLabel(node, text, rect.w / 2, rect.h / 2, 20, C_TEXT);
    node.touchEnabled = true;
    node.onTapped(() => onTap());
    node.addTo(this.actionLayer);
  }

  // 点击背包硬币：放到当前选中的卡牌上；未选中卡牌时给出提示。
  private placeCoinOnSelected(type: CoinType, value: number): void {
    if (this.mgr.state.status !== 'playing') return;
    if (this.selectedCardId === undefined) {
      this.hintText = '先点一张卡牌，再点硬币';
      this.refresh();
      return;
    }
    const card = this.mgr.findCard(this.selectedCardId);
    if (!card) {
      this.selectedCardId = undefined;
      this.refresh();
      return;
    }
    const ok = this.mgr.placeCoinOnCard(card.id, type, value);
    this.hintText = ok ? '' : '这枚硬币放不上去';
    this.refresh();
  }
