    const fill = selected ? Color(44, 58, 104, 255) : C_CARD;

    const d = DrawNode();
    d.drawPolygon(rectVerts(0, 0, CARD_W, CARD_H), fill, borderW, border);
    // 倒计时徽章（外圈 + 内芯）
    d.drawDot(Vec2(70, 98), 21, C_PANEL_BORDER);
    d.drawDot(Vec2(70, 98), 18, C_BADGE);
    d.addTo(node);

