    makeLabel(node, '回合', 70, 122, 9, C_TEXT_DIM);

    // 特殊状态徽章（折扣/冰冻/回复/复制）
    let bx = -88;
    const by = 106;
    if (card.target !== card.originalTarget) {
      d.drawDot(Vec2(bx, by), 10, coinColor(CoinType.Discount));
      makeLabel(node, '折', bx, by, 10, C_TEXT);
