```
  // 触摸点到世界（= 设计中心）坐标：用节点自身变换把节点本地坐标转世界坐标。
  private touchWorld(t: Touch.Type, node: Node.Type): Vec2.Type {
    return node.convertToWorldSpace(t.location);
  }

  private beginDrag(
    kind: 'inventory' | 'placed',
    cardId: number,
    index: number,
    type: CoinType,
    value: number,
    t: Touch.Type,
    node: Node.Type,
  ): void {
    this.drag = { kind: kind, cardId: cardId, index: index, type: type, value: value };
    const wp = this.touchWorld(t, node);
    this.dragStart = wp;
    this.makeGhost(type, value, wp);
  }

  private moveDrag(t: Touch.Type, node: Node.Type): void {
    if (!this.drag) return;
    const wp = this.touchWorld(t, node);
    if (this.dragGhost) this.dragGhost.position = wp;
  }

  private endDrag(t: Touch.Type, node: Node.Type): void {
    const d = this.drag;
    this.drag = undefined;
    this.hideGhost();
    const start = this.dragStart;
    this.dragStart = undefined;
    if (!d) return;
    const wp = this.touchWorld(t, node);
    const moved = start ? Math.abs(wp.x - start.x) + Math.abs(wp.y - start.y) : 0;
    const isTap = moved < 18;
    if (d.kind === 'inventory') {
      if (isTap) {
        this.placeCoinOnSelected(d.type, d.value);
        return;
      }
      const target = this.cardAtPoint(wp);
      if (target !== undefined) {
        this.mgr.placeCoinOnCard(target, d.type, d.value);
        this.hintText = '';
      } else {
        this.hintText = '把硬币拖到某张卡牌上';
      }
      this.refresh();
    } else {
      if (isTap) {
        this.mgr.removePlacedCoin(d.cardId, d.index);
        this.refresh();
        return;
      }
      const target = this.cardAtPoint(wp);
      if (target === undefined) {
        this.mgr.removePlacedCoin(d.cardId, d.index);
      } else if (target !== d.cardId) {
        this.mgr.movePlacedCoin(d.cardId, d.index, target);
      }
      this.refresh();
    }
  }

  private cardAtPoint(p: Vec2.Type): number | undefined {
    for (let i = 0; i < this.cardRects.length; i++) {
      const r = this.cardRects[i];
      if (p.x >= r.x - r.w / 2 && p.x <= r.x + r.w / 2 &&
        p.y >= r.y - r.h / 2 && p.y <= r.y + r.h / 2) {
        return r.id;
      }
    }
    return undefined;
  }

  private makeGhost(type: CoinType, value: number, pos: Vec2.Type): void {
    this.hideGhost();
    const node = Node();
    node.position = pos;
    const d = DrawNode();
    d.drawDot(Vec2.zero, 26, coinColor(type));
    d.drawDot(Vec2.zero, 20, C_BADGE);
    d.addTo(node);
    const l = Label('sarasa-mono-sc-regular', 18);
    if (l) { l.text = coinChipText(type, value); l.position = Vec2.zero; l.color = C_TEXT; l.addTo(node); }
    node.addTo(this.fxLayer);
    this.dragGhost = node;
  }

  private hideGhost(): void {
    if (this.dragGhost) { this.dragGhost.removeFromParent(); this.dragGhost = undefined; }
  }
