// 切换背包中某硬币数值的正负号（合并到目标堆叠）
flipCoinSign(type: CoinType, value: number): void {
  const inv = this.state.inventory;
  for (let i = 0; i < inv.length; i++) {
    const s = inv[i];
    if (s.type === type && s.value === value) {
      const count = s.count;
      inv.splice(i, 1);
      this.addToStack(inv, type, -value, count);
      return;
    }
  }
}
```

