  placeCoinOnCard(cardId: number, type: CoinType, value: number): boolean {
    const card = this.findCard(cardId);
    if (!card || card.eliminated) return false;
    if (this.stackCount(type, value) <= 0) return false;

    // 特殊硬币：放置即生效
