    if (type === CoinType.Heal) { card.healAmount += value; this.consumeCoin(type, value, 1); return true; }
    if (type === CoinType.Copy) { card.copyArmed = true; this.consumeCoin(type, value, 1); return true; }
    if (type === CoinType.Wild) { this.consumeCoin(type, value, 1); this.eliminateCard(card); return true; }

    // 算式硬币：普通 / 乘法 / 增长 / 干扰
    let op = 'add';
    if (type === CoinType.Multiply) op = 'mul';
    const placed: PlacedCoin = { type: type, value: value, op: op };
    card.coins.push(placed);
    this.consumeCoin(type, value, 1);
    return true;
  }
