// 设计尺寸（逻辑坐标系，所有 UI 都在此坐标系内布局）
export const DESIGN_W = 720;
export const DESIGN_H = 1280;

// 卡牌网格参数（一行三张）
const CARD_COLS = 3;
const CARD_ROWS = 1;
const CARD_W = 200;
const CARD_H = 300;
const CARD_GAP_X = 14;
const CARD_GAP_Y = 14;

// 颜色常量
const C_BG: Color.Type = Color(12, 16, 34, 255);
const C_PANEL: Color.Type = Color(22, 30, 56, 255);
