import { Content, Path } from 'Dora';
import { GameDataManager } from 'game/GameDataManager';
import { CoinType } from 'game/types';

const resultDir = Path(Content.searchPaths[0], '.agent', 'test-results');
if (!Content.exist(resultDir)) Content.mkdir(resultDir);

const lines: string[] = [];
const mgr = new GameDataManager();
const card = mgr.state.cards[0];

// 1. Normal 硬币 3 的初始数量
const before = mgr.stackCount(CoinType.Normal, 3);
lines.push('normal+3 count=' + before);

// 2. 翻转符号
mgr.flipCoinSign(CoinType.Normal, 3);
const minus = mgr.stackCount(CoinType.Normal, -3);
const plusAfter = mgr.stackCount(CoinType.Normal, 3);
lines.push('after flip: +3=' + plusAfter + ' -3=' + minus);

// 3. 放置负数硬币
const placed = mgr.placeCoinOnCard(card.id, CoinType.Normal, -3);
const pc = card.coins[card.coins.length - 1];
lines.push('place -3 ok=' + placed + ' op=' + pc.op + ' value=' + pc.value + ' eval=' + mgr.evaluateCard(card));

// 4. 点击已放置硬币切换符号
mgr.togglePlacedCoin(card.id, card.coins.length - 1);
lines.push('after toggle op=' + pc.op + ' eval=' + mgr.evaluateCard(card));

// 5. 移除已放置硬币，归还符号
mgr.togglePlacedCoin(card.id, card.coins.length - 1); // 转回 sub
const removed = mgr.removePlacedCoin(card.id, card.coins.length - 1);
lines.push('remove ok=' + removed + ' restored -3=' + mgr.stackCount(CoinType.Normal, -3));

Content.save(Path(resultDir, 'coin-logic.txt'), lines.join('\n'));
```

