// 设计尺寸（逻辑坐标系，所有 UI 都在此坐标系内布局）
export const DESIGN_W = 720;
export const DESIGN_H = 1280;

// 卡牌网格参数（一行三张）
const CARD_COLS = 3;
const CARD_ROWS = 1;
const CARD_W = 200;
const CARD_H = 300;
const CARD_GAP_X = 14;
const CARD_GAP_Y = 14;

// 颜色常量
const C_BG: Color.Type = Color(12, 16, 34, 255);
const C_PANEL: Color.Type = Color(22, 30, 56, 255);
const C_PANEL_BORDER: Color.Type = Color(64, 84, 132, 255);
const C_CARD: Color.Type = Color(30, 40, 74, 255);
const C_CARD_BORDER: Color.Type = Color(86, 110, 170, 255);
const C_GROUP: Color.Type = Color(26, 36, 66, 255);
const C_TEXT: Color.Type = Color(235, 240, 255, 255);
const C_TEXT_DIM: Color.Type = Color(150, 160, 190, 255);
const C_TEXT_FAINT: Color.Type = Color(220, 230, 255, 255);
const C_DANGER: Color.Type = Color(255, 92, 92, 255);
const C_CONFIRM: Color.Type = Color(72, 186, 112, 255);
const C_CONFIRM_BORDER: Color.Type = Color(150, 255, 180, 255);
const C_ENDTURN: Color.Type = Color(206, 126, 62, 255);
const C_BADGE: Color.Type = Color(16, 22, 46, 255);

// 硬币类型对应的颜色
function coinColor(type: CoinType): Color.Type {
  switch (type) {
    case CoinType.Normal: return Color(84, 160, 255, 255);
    case CoinType.Multiply: return Color(255, 140, 82, 255);
    case CoinType.Freeze: return Color(120, 210, 255, 255);
    case CoinType.Discount: return Color(186, 140, 255, 255);
    case CoinType.Copy: return Color(255, 120, 200, 255);
    case CoinType.Wild: return Color(255, 208, 90, 255);
    case CoinType.Growth: return Color(140, 255, 170, 255);
    case CoinType.Heal: return Color(120, 224, 140, 255);
    case CoinType.Disturb: return Color(255, 92, 92, 255);
    default: return Color(200, 200, 200, 255);
  }
}

// 硬币芯片显示文本（按类型显示有意义的符号/数值）
function coinChipText(type: CoinType, value: number): string {
  switch (type) {
    case CoinType.Freeze: return '冻';
    case CoinType.Discount: return value + '%';
    case CoinType.Copy: return '复';
    case CoinType.Wild: return '万';
    case CoinType.Heal: return (value >= 0 ? '+' : '') + value;
    case CoinType.Growth: return '' + value;
    case CoinType.Normal:
    case CoinType.Multiply:
    case CoinType.Disturb:
    default: return '' + value;
  }
}

// 以中心点为基准的矩形顶点
function rectVerts(cx: number, cy: number, w: number, h: number): Vec2.Type[] {
  return [
    Vec2(cx - w / 2, cy - h / 2),
    Vec2(cx + w / 2, cy - h / 2),
    Vec2(cx + w / 2, cy + h / 2),
    Vec2(cx - w / 2, cy + h / 2),
  ];
}

// 便捷创建居中文本
function makeLabel(
  parent: Node.Type,
  text: string,
  x: number,
  y: number,
  size: number,
  color: Color.Type,
  anchor?: Vec2.Type,
): Label.Type | undefined {
  const l = Label('sarasa-mono-sc-regular', size);
  if (!l) return undefined;
  l.text = text;
  l.position = Vec2(x, y);
  l.anchor = anchor ? anchor : Vec2(0.5, 0.5);
  l.color = color;
  l.addTo(parent);
  return l;
}

