    Vec2(cx + w / 2, cy - h / 2),
    Vec2(cx + w / 2, cy + h / 2),
    Vec2(cx - w / 2, cy + h / 2),
  ];
}

// 便捷创建居中文本
function makeLabel(
  parent: Node.Type,
  text: string,
  x: number,
  y: number,
  size: number,
  color: Color.Type,
  anchor?: Vec2.Type,
): Label.Type | undefined {
  const l = Label('sarasa-mono-sc-regular', size);
  if (!l) return undefined;
  l.text = text;
  l.position = Vec2(x, y);
  l.anchor = anchor ? anchor : Vec2(0.5, 0.5);
  l.color = color;
  l.addTo(parent);
  return l;
}

