import { App, Audio, Color, Director, DrawNode, Label, Mouse, Node, Size, Touch, TypeName, Vec2, View, tolua } from 'Dora';
import { Card, CoinStack, CoinType, COIN_TYPE_ORDER, coinTypeName } from 'game/types';
import { GameDataManager } from 'game/GameDataManager';

// 设计尺寸（逻辑坐标系，所有 UI 都在此坐标系内布局）
export const DESIGN_W = 720;
export const DESIGN_H = 1280;

// 卡牌网格参数（一行三张）
const CARD_COLS = 3;
const CARD_ROWS = 1;
const CARD_W = 200;
const CARD_H = 300;
const CARD_GAP_X = 14;
const CARD_GAP_Y = 14;

// 颜色常量（古典暗金属：暗棕青铜底 + 金色描边 + 羊皮纸文字）
const C_BG: Color.Type = Color(14, 12, 10, 255);
const C_PANEL: Color.Type = Color(26, 20, 15, 255);
const C_PANEL_BORDER: Color.Type = Color(96, 73, 34, 255);
const C_CARD: Color.Type = Color(28, 22, 17, 255);
const C_CARD_BORDER: Color.Type = Color(176, 138, 64, 255);
const C_GROUP: Color.Type = Color(30, 23, 17, 255);
const C_TEXT: Color.Type = Color(234, 220, 190, 255);
const C_TEXT_DIM: Color.Type = Color(158, 141, 112, 255);
const C_TEXT_FAINT: Color.Type = Color(214, 186, 120, 255);
const C_DANGER: Color.Type = Color(186, 66, 52, 255);
const C_CONFIRM: Color.Type = Color(150, 116, 54, 255);
const C_CONFIRM_BORDER: Color.Type = Color(234, 206, 138, 255);
const C_ENDTURN: Color.Type = Color(92, 62, 38, 255);
const C_BADGE: Color.Type = Color(16, 13, 10, 255);
const C_GOLD: Color.Type = Color(176, 138, 64, 255);
const C_GOLD_BRIGHT: Color.Type = Color(234, 206, 138, 255);
const C_GOLD_DARK: Color.Type = Color(96, 73, 34, 255);
const C_GOLD_TEXT: Color.Type = Color(214, 186, 120, 255);

// 硬币类型对应的颜色
function coinColor(type: CoinType): Color.Type {
  switch (type) {
    case CoinType.Normal: return Color(84, 160, 255, 255);
    case CoinType.Multiply: return Color(255, 140, 82, 255);
    case CoinType.Freeze: return Color(120, 210, 255, 255);
    case CoinType.Discount: return Color(186, 140, 255, 255);
    case CoinType.Copy: return Color(255, 120, 200, 255);
    case CoinType.Wild: return Color(255, 208, 90, 255);
    case CoinType.Growth: return Color(140, 255, 170, 255);
    case CoinType.Heal: return Color(120, 224, 140, 255);
    case CoinType.Disturb: return Color(255, 92, 92, 255);
    default: return Color(200, 200, 200, 255);
  }
}

// 硬币芯片显示文本（按类型显示有意义的符号/数值）
function coinChipText(type: CoinType, value: number): string {
  switch (type) {
    case CoinType.Freeze: return '冻';
    case CoinType.Discount: return value + '%';
    case CoinType.Copy: return '复';
    case CoinType.Wild: return '万';
    case CoinType.Heal: return (value >= 0 ? '+' : '') + value;
    case CoinType.Growth: return '' + value;
    case CoinType.Normal:
    case CoinType.Multiply:
    case CoinType.Disturb:
    default: return '' + value;
