```ts
  private renderLevels(): void {
    const maxLevel = GameDataManager.MAX_LEVEL;
    const unlocked = Math.min(maxLevel, Math.max(1, this.mgr.state.highestLevel));

    // 背景面板 + 连线
    const d = DrawNode();
    drawGrad(d, 0, 0, 660, 900, [50, 38, 68, 255], [22, 17, 32, 255]);
    drawBand(d, 0, 0, 660, 900, 3, C_GOLD_DARK);
    drawBand(d, 0, 0, 660, 900, 1, C_GOLD);
    drawCorners(d, 0, 0, 660, 900, 14, 8, C_GOLD_BRIGHT);

    const cols = [-200, 0, 200];
    const rows = [330, 140, -50, -240, -430];
    // 计算每个关卡的坐标
    const px: number[] = [];
    const py: number[] = [];
    for (let i = 0; i < maxLevel; i++) {
      const row = Math.floor(i / 3);
      const col = i % 3;
      const c = (row % 2 === 0) ? col : (2 - col);
      px.push(cols[c]);
      py.push(rows[row]);
    }
    // 连线
    for (let i = 0; i + 1 < maxLevel; i++) {
      d.drawSegment(Vec2(px[i], py[i]), Vec2(px[i + 1], py[i + 1]), 3, C_GOLD_DARK);
    }
    d.addTo(this.screenLayer);

    makeLabel(this.screenLayer, '选择关卡', 0, 500, 40, C_GOLD_TEXT);
    makeLabel(this.screenLayer, '共 ' + maxLevel + ' 关 · 已解锁 ' + unlocked, 0, 448, 22, C_TEXT_DIM);

    // 关卡节点
    for (let i = 0; i < maxLevel; i++) {
      const lv = i + 1;
      const open = lv <= unlocked;
      const x = px[i];
      const y = py[i];

      const nd = DrawNode();
      if (open) {
        nd.drawDot(Vec2(x, y), 40, C_GOLD);
        nd.drawDot(Vec2(x, y), 34, C_BADGE);
      } else {
        nd.drawDot(Vec2(x, y), 40, Color(52, 44, 66, 255));
        nd.drawDot(Vec2(x, y), 34, Color(26, 20, 34, 255));
      }
      nd.addTo(this.screenLayer);
      makeLabel(this.screenLayer, '' + lv, x, y, open ? 26 : 22, open ? C_GOLD_TEXT : Color(96, 86, 112, 255));

      if (open) {
        const hit = Node();
        hit.position = Vec2(x, y);
        hit.size = Size(84, 84);
        hit.anchor = Vec2(0.5, 0.5);
        hit.touchEnabled = true;
        hit.onTapped(() => this.startLevelAt(lv));
        hit.addTo(this.screenLayer);
      }
    }

    this.makeButton({ x: 0, y: -540, w: 240, h: 62 }, '返回', [132, 106, 172, 255], [74, 55, 100, 255], Color(234, 226, 250, 255), () => this.goMenu(), this.screenLayer);
  }
```

