  drawStud(d, cx - hx, cy + hy, r, color);
  drawStud(d, cx + hx, cy + hy, r, color);
  drawStud(d, cx - hx, cy - hy, r, color);
  drawStud(d, cx + hx, cy - hy, r, color);
}

