}

// ===== 入口：渲染一帧后导出 =====
const scene = Node();
scene.addTo(Director.entry);
scene.schedule(() => {
  // RenderTarget.saveAsync 必须在协程（thread）中执行
  thread(() => {
    buildIcon();
    buildCover();
