  // 开始指定关卡
  startLevel(level: number): void {
    let lvl = level;
    if (lvl < 1) lvl = 1;
    if (lvl > GameDataManager.MAX_LEVEL) lvl = GameDataManager.MAX_LEVEL;
    if (lvl > this.highestLevel) this.highestLevel = lvl;
