      if (!found) names.push(name);
    }
    let out = '';
    for (let i = 0; i < names.length; i++) {
      if (i > 0) out += '/';
      out += names[i];
    }
    return out;
  }

  // 随机整数 [min, max]
  randomInt(min: number, max: number): number {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  // 发一张卡牌
  private dealCard(): void {
    const pool = GameDataManager.TARGET_POOL;
