    const skills = this.shuffleCoins(this.expandCoins(this.buildSkillCoins()));
    for (let i = 0; i < skills.length; i++) queue.push(skills[i]);
    const extraList = this.shuffleCoins(this.expandCoins(extra));
    for (let i = 0; i < extraList.length; i++) queue.push(extraList[i]);

    const hand: CoinStack[] = [];
